const fs = require('node:fs');
const path = require('node:path');

const root = path.resolve(__dirname, '..');
const sources = [
  'node_modules/marked/lib/marked.umd.js',
  'node_modules/dompurify/dist/purify.min.js',
];
const scripts = sources.map(source => {
  const code = fs.readFileSync(path.join(root, source), 'utf8');
  if (/<\/script/i.test(code)) throw new Error('Cannot embed a closing script tag in ' + source);
  return '<script>\n' + code + '\n</script>';
});
fs.writeFileSync(path.join(root, 'MarkdownLibraries.html'),
  '<!-- Generated by npm run build:markdown. Library license notices are preserved. -->\n' + scripts.join('\n') + '\n');
